import AppKit
import ImageIO
import UniformTypeIdentifiers
import XCTest

/// Synthetic preview fixtures, written once per test process into the temporary directory.
///
/// These used to be generated by scripts into `lab/fixtures/v03`, which is not tracked, so a clean
/// checkout had no fixtures and every preview test failed on a missing file. Building them here
/// keeps the suite self-contained. Nothing personal goes in.
enum TestFixtures {
  static func url(_ name: String) -> URL {
    root.appendingPathComponent(name)
  }

  static func data(_ name: String) throws -> Data {
    let url = url(name)
    XCTAssertTrue(FileManager.default.fileExists(atPath: url.path), url.path)
    return try Data(contentsOf: url)
  }

  private static let prefix = "WitsCopyTestFixtures-"

  private static let root: URL = {
    let temporary = FileManager.default.temporaryDirectory
    removeStaleFixtures(in: temporary)
    let root = temporary
      .appendingPathComponent("\(prefix)\(ProcessInfo.processInfo.processIdentifier)", isDirectory: true)
    do {
      try? FileManager.default.removeItem(at: root)
      try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
      try writeImages(into: root)
      try writeTexts(into: root)
      try writeDocx(into: root)
    } catch {
      XCTFail("could not build test fixtures: \(error)")
    }
    return root
  }()

  /// Each test process writes its own fixture folder, named by pid so parallel
  /// runs never share one. Folders of processes that have exited are leftovers.
  private static func removeStaleFixtures(in directory: URL) {
    let names = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []
    for name in names where name.hasPrefix(prefix) {
      guard let pid = Int32(name.dropFirst(prefix.count)),
            pid != ProcessInfo.processInfo.processIdentifier,
            kill(pid, 0) != 0 else { continue }
      try? FileManager.default.removeItem(at: directory.appendingPathComponent(name, isDirectory: true))
    }
  }

  // MARK: - Images, GIF, PDF

  private static let canvas = CGSize(width: 720, height: 260)

  private static func image(_ title: String, subtitle: String = "", color: NSColor = .white) -> CGImage {
    let bitmap = NSBitmapImageRep(
      bitmapDataPlanes: nil,
      pixelsWide: Int(canvas.width),
      pixelsHigh: Int(canvas.height),
      bitsPerSample: 8,
      samplesPerPixel: 4,
      hasAlpha: true,
      isPlanar: false,
      colorSpaceName: .deviceRGB,
      bytesPerRow: 0,
      bitsPerPixel: 0
    )!
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: bitmap)
    color.setFill()
    NSBezierPath(rect: NSRect(origin: .zero, size: canvas)).fill()
    (title as NSString).draw(
      at: NSPoint(x: 28, y: 150),
      withAttributes: [.font: NSFont.monospacedSystemFont(ofSize: 40, weight: .bold), .foregroundColor: NSColor.black]
    )
    (subtitle as NSString).draw(
      at: NSPoint(x: 28, y: 65),
      withAttributes: [.font: NSFont.systemFont(ofSize: 30), .foregroundColor: NSColor.black]
    )
    NSGraphicsContext.restoreGraphicsState()
    return bitmap.cgImage!
  }

  private static func writeImages(into root: URL) throws {
    func png(_ image: CGImage, _ name: String) throws {
      let url = root.appendingPathComponent(name) as CFURL
      guard let dest = CGImageDestinationCreateWithURL(url, UTType.png.identifier as CFString, 1, nil) else {
        throw CocoaError(.fileWriteUnknown)
      }
      CGImageDestinationAddImage(dest, image, nil)
      guard CGImageDestinationFinalize(dest) else { throw CocoaError(.fileWriteUnknown) }
    }
    try png(image("WIT OCR 2026", subtitle: "剪贴板预览测试"), "ocr-bilingual.png")
    try png(image("SECOND IMAGE 482", subtitle: "取消旧任务，不要串图"), "ocr-second.png")

    let delays: [Double] = [0.12, 0.64, 0.18, 0.82]
    let colors: [NSColor] = [.systemYellow, .systemGreen, .systemCyan, .systemOrange]
    let gifURL = root.appendingPathComponent("timing-irregular.gif") as CFURL
    guard let gif = CGImageDestinationCreateWithURL(gifURL, UTType.gif.identifier as CFString, delays.count, nil) else {
      throw CocoaError(.fileWriteUnknown)
    }
    CGImageDestinationSetProperties(
      gif,
      [kCGImagePropertyGIFDictionary: [kCGImagePropertyGIFLoopCount: 0]] as CFDictionary
    )
    for (index, delay) in delays.enumerated() {
      CGImageDestinationAddImage(
        gif,
        image("FRAME \(index + 1)", subtitle: "source delay \(delay) seconds", color: colors[index]),
        [kCGImagePropertyGIFDictionary: [
          kCGImagePropertyGIFDelayTime: delay,
          kCGImagePropertyGIFUnclampedDelayTime: delay
        ]] as CFDictionary
      )
    }
    guard CGImageDestinationFinalize(gif) else { throw CocoaError(.fileWriteUnknown) }

    var mediaBox = CGRect(x: 0, y: 0, width: 612, height: 792)
    let pdfURL = root.appendingPathComponent("two-page-selectable.pdf") as CFURL
    guard let pdf = CGContext(pdfURL, mediaBox: &mediaBox, nil) else { throw CocoaError(.fileWriteUnknown) }
    for page in 1...2 {
      pdf.beginPDFPage(nil)
      NSGraphicsContext.saveGraphicsState()
      NSGraphicsContext.current = NSGraphicsContext(cgContext: pdf, flipped: false)
      ("WIT PDF PAGE \(page)" as NSString).draw(
        at: NSPoint(x: 48, y: 680),
        withAttributes: [.font: NSFont.systemFont(ofSize: 28), .foregroundColor: NSColor.black]
      )
      ("Selectable text. Preview only, original file stays intact." as NSString).draw(
        at: NSPoint(x: 48, y: 620),
        withAttributes: [.font: NSFont.systemFont(ofSize: 16), .foregroundColor: NSColor.black]
      )
      NSGraphicsContext.restoreGraphicsState()
      pdf.endPDFPage()
    }
    pdf.closePDF()
  }

  // MARK: - Text

  private static func writeTexts(into root: URL) throws {
    let texts: [String: String] = [
      "readme.md": """
        # Preview heading

        This is **bold** and *emphasis*.

        - First item
        - 中文条目

        ```swift
        let message = "WIT"
        print(message)
        ```

        | Name | Value |
        | --- | --- |
        | Local | 2026 |

        [Offline link](https://example.invalid/)

        ![Must not load remotely](https://example.invalid/no-network.png)

        """,
      "sample.swift": """
        import Foundation

        // Native source preview; preserve indentation.
        struct Sample {
            let greeting = "Hello, 世界"
            func run() {
                print(greeting)
            }
        }

        """,
      "large.txt": (0..<24_000)
        .map { String(format: "Line %06d — bounded preview, full source retained.\n", $0) }
        .joined()
    ]
    for (name, text) in texts {
      try text.write(to: root.appendingPathComponent(name), atomically: true, encoding: .utf8)
    }
  }

  // MARK: - DOCX

  private static func writeDocx(into root: URL) throws {
    let staging = root.appendingPathComponent("docx-src", isDirectory: true)
    let parts: [String: String] = [
      "[Content_Types].xml": """
        <?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">\
        <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>\
        <Default Extension="xml" ContentType="application/xml"/>\
        <Override PartName="/word/document.xml" \
        ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>
        """,
      "_rels/.rels": """
        <?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\
        <Relationship Id="rId1" \
        Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" \
        Target="word/document.xml"/></Relationships>
        """,
      "word/document.xml": """
        <?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">\
        <w:body><w:p><w:r><w:rPr><w:b/><w:sz w:val="36"/></w:rPr><w:t>WIT WORD DOCUMENT</w:t></w:r></w:p>\
        <w:p><w:r><w:t>Native Quick Look office preview.</w:t></w:r></w:p>\
        <w:p><w:r><w:t>中文内容：这是真实的合成 DOCX 文件。</w:t></w:r></w:p>\
        <w:sectPr><w:pgSz w:w="11906" w:h="16838"/>\
        <w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>
        """
    ]
    for (path, xml) in parts {
      let url = staging.appendingPathComponent(path)
      try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
      try xml.write(to: url, atomically: true, encoding: .utf8)
    }
    // ditto -c -k zips the directory's contents with no parent folder, which is the DOCX layout.
    let zip = Process()
    zip.executableURL = URL(fileURLWithPath: "/usr/bin/ditto")
    zip.arguments = ["-c", "-k", "--norsrc", staging.path, root.appendingPathComponent("sample.docx").path]
    try zip.run()
    zip.waitUntilExit()
    guard zip.terminationStatus == 0 else { throw CocoaError(.fileWriteUnknown) }
    try FileManager.default.removeItem(at: staging)
  }
}

/// `removePersistentDomain` empties a defaults domain but cfprefsd leaves its
/// plist file in ~/Library/Preferences. Tests that create throwaway domains
/// remove both, so repeated runs do not pile up empty preference files.
enum TestDefaults {
  static func discard(_ domain: String) {
    UserDefaults(suiteName: domain)?.removePersistentDomain(forName: domain)
    CFPreferencesAppSynchronize(domain as CFString)
    let file = FileManager.default.homeDirectoryForCurrentUser
      .appendingPathComponent("Library/Preferences/\(domain).plist")
    try? FileManager.default.removeItem(at: file)
  }

  /// cfprefsd may flush a discarded domain back to disk after the test ends,
  /// so tests that mint a fresh domain per run also sweep earlier ones.
  static func removeLeftovers(prefix: String) {
    let folder = FileManager.default.homeDirectoryForCurrentUser
      .appendingPathComponent("Library/Preferences", isDirectory: true)
    let names = (try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []
    for name in names where name.hasPrefix(prefix) && name.hasSuffix(".plist") {
      discard(String(name.dropLast(".plist".count)))
    }
  }
}
